FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL := FALSE;
END_VAR
VAR
    state      : INT;
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
END_VAR

DEFINE
    IDLE    := 0;
    OPENING := 1;
    CLOSING := 2;
    FAULT   := 3;
END_DEFINE

(* Rising edge detection *)
VAR
    openRising  : BOOL;
    closeRising : BOOL;
END_VAR

openRising  := openBtn AND NOT prevOpenBtn;
closeRising := closeBtn AND NOT prevCloseBtn;
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

(* State machine *)
IF state = FAULT THEN
    IF openBtn AND closeBtn THEN
        state     := IDLE;
        errorFlag := FALSE;
    END_IF
    (* No other transitions from FAULT *)
ELSIF state = CLOSING THEN
    IF obstacle THEN
        state    := OPENING;
        motorUp   := TRUE;
        motorDown := FALSE;
    END_IF;
ELSIF state = OPENING THEN
    IF obstacle THEN
        state     := FAULT;
        errorFlag := TRUE;
        motorUp   := FALSE;
    END_IF;
END_IF;

(* Transitions triggered by rising edges (only when not in FAULT) *)
IF state <> FAULT THEN
    IF openRising AND NOT openLimit THEN
        state    := OPENING;
    ELSIF closeRising AND NOT closeLimit THEN
        state    := CLOSING;
    END_IF;
END_IF;

(* Motor output based on current state *)
motorUp   := (state = OPENING);
motorDown := (state = CLOSING);

(* Safety: motorUp only allowed in OPENING *)
IF state <> OPENING AND motorUp THEN
    motorUp := FALSE;
END_IF;

(* Safety: motorDown only allowed in CLOSING *)
IF state <> CLOSING AND motorDown THEN
    motorDown := FALSE;
END_IF;

(* Safety: mutual exclusion *)
IF motorUp AND motorDown THEN
    motorDown := FALSE;
END_IF;

END_FUNCTION_BLOCK
